// Helper function providing vibrant, consistent color identities for each Madrasa class
export const getClassColor = (classLevel: string | null | undefined) => {
  if (!classLevel) {
    return {
      badge: "bg-slate-800 text-white border-slate-700",
      card: "bg-slate-50 border-slate-200 text-slate-900",
      dot: "bg-slate-500",
      ring: "ring-slate-400",
      pill: "bg-slate-800 text-white",
      name: classLevel || "Unknown",
    };
  }
  const clean = classLevel.trim();
  const digits = clean.match(/\d+/);
  const num = digits ? parseInt(digits[0], 10) : 0;

  switch (num) {
    case 1:
      return {
        badge: "bg-blue-600 text-white border-blue-700",
        card: "bg-blue-50/90 border-blue-200 text-blue-950",
        dot: "bg-blue-600",
        ring: "ring-blue-400",
        pill: "bg-blue-600 text-white",
        name: clean,
      };
    case 2:
      return {
        badge: "bg-emerald-600 text-white border-emerald-700",
        card: "bg-emerald-50/90 border-emerald-200 text-emerald-950",
        dot: "bg-emerald-600",
        ring: "ring-emerald-400",
        pill: "bg-emerald-600 text-white",
        name: clean,
      };
    case 3:
      return {
        badge: "bg-amber-600 text-white border-amber-700",
        card: "bg-amber-50/90 border-amber-200 text-amber-950",
        dot: "bg-amber-500",
        ring: "ring-amber-400",
        pill: "bg-amber-600 text-white",
        name: clean,
      };
    case 4:
      return {
        badge: "bg-purple-600 text-white border-purple-700",
        card: "bg-purple-50/90 border-purple-200 text-purple-950",
        dot: "bg-purple-600",
        ring: "ring-purple-400",
        pill: "bg-purple-600 text-white",
        name: clean,
      };
    case 5:
      return {
        badge: "bg-rose-600 text-white border-rose-700",
        card: "bg-rose-50/90 border-rose-200 text-rose-950",
        dot: "bg-rose-600",
        ring: "ring-rose-400",
        pill: "bg-rose-600 text-white",
        name: clean,
      };
    case 6:
      return {
        badge: "bg-sky-600 text-white border-sky-700",
        card: "bg-sky-50/90 border-sky-200 text-sky-950",
        dot: "bg-sky-600",
        ring: "ring-sky-400",
        pill: "bg-sky-600 text-white",
        name: clean,
      };
    case 7:
      return {
        badge: "bg-fuchsia-600 text-white border-fuchsia-700",
        card: "bg-fuchsia-50/90 border-fuchsia-200 text-fuchsia-950",
        dot: "bg-fuchsia-600",
        ring: "ring-fuchsia-400",
        pill: "bg-fuchsia-600 text-white",
        name: clean,
      };
    case 8:
      return {
        badge: "bg-teal-600 text-white border-teal-700",
        card: "bg-teal-50/90 border-teal-200 text-teal-950",
        dot: "bg-teal-600",
        ring: "ring-teal-400",
        pill: "bg-teal-600 text-white",
        name: clean,
      };
    case 9:
      return {
        badge: "bg-lime-700 text-white border-lime-800",
        card: "bg-lime-50/90 border-lime-200 text-lime-950",
        dot: "bg-lime-600",
        ring: "ring-lime-400",
        pill: "bg-lime-700 text-white",
        name: clean,
      };
    case 10:
      return {
        badge: "bg-indigo-700 text-white border-indigo-800",
        card: "bg-indigo-50/90 border-indigo-200 text-indigo-950",
        dot: "bg-indigo-600",
        ring: "ring-indigo-400",
        pill: "bg-indigo-700 text-white",
        name: clean,
      };
    case 11:
      return {
        badge: "bg-violet-700 text-white border-violet-800",
        card: "bg-violet-50/90 border-violet-200 text-violet-950",
        dot: "bg-violet-600",
        ring: "ring-violet-400",
        pill: "bg-violet-700 text-white",
        name: clean,
      };
    case 12:
      return {
        badge: "bg-orange-600 text-white border-orange-700",
        card: "bg-orange-50/90 border-orange-200 text-orange-950",
        dot: "bg-orange-600",
        ring: "ring-orange-400",
        pill: "bg-orange-600 text-white",
        name: clean,
      };
    default:
      return {
        badge: "bg-slate-800 text-white border-slate-700",
        card: "bg-slate-50 border-slate-200 text-slate-900",
        dot: "bg-slate-500",
        ring: "ring-slate-400",
        pill: "bg-slate-800 text-white",
        name: clean,
      };
  }
};

