  // --- BATCH 7-DAY EXAM SEATING GENERATOR STATE ---
  const [showBatchModal, setShowBatchModal] = useState<boolean>(false);
  const [batchStrategy, setBatchStrategy] = useState<"dispersion" | "standard">("dispersion");
  const [batchResults, setBatchResults] = useState<Record<number, SeatingResult>>({});
  const [showRecalculateDropdown, setShowRecalculateDropdown] = useState<boolean>(false);
  const [selectedBatchDay, setSelectedBatchDay] = useState<number>(1);

  const handleBatchGenerateAllDays = () => {
    const results: Record<number, SeatingResult> = {};
    let totalGenerated = 0;
    const allDays = Object.values(classTimetableMap).flatMap((list: any) => (Array.isArray(list) ? list : []).map((item: any) => item.dayNum));
    const maxDay = allDays.length > 0 ? Math.max(...allDays) : 7;
    for (let d = 1; d <= maxDay; d++) {
      const filteredStus = getFilteredStudentsForDay(d);
      if (filteredStus.length > 0) {
        try {
          // Filter halls to those that are not reserved for other shifts or are flexible
          // If mapping exists for this day, only use mapped halls
          const mappedHalls = hallDayMapping[d] || [];
          const allDayHalls = halls.filter(h => !h.reservedShift || h.reservedShift === "None" || h.reservedShift === activeShift);
          const dayHalls = mappedHalls.length > 0 
            ? allDayHalls.filter(h => mappedHalls.includes(h.id))
            : allDayHalls;
          const res = runSeatingAllocation(filteredStus, dayHalls, activeShift, variationSeed + d, lang, seatingStrategy);
          results[d] = res;
          totalGenerated++;
        } catch (e) {
          console.error(`Batch generation error for day ${d}`, e);
        }
      }
    }
    setBatchResults(results);
    setShowBatchModal(false);
    setShowRecalculateDropdown(false);
    setSelectedBatchDay(1);
    if (results[1]) {
      setSeatingResult(results[1]);
      setDailyShufflingResult({
        dayNum: 1,
        result: results[1],
        activeClasses: Array.from(new Set(getFilteredStudentsForDay(1).map(s => s.classLevel))),
        studentCount: getFilteredStudentsForDay(1).length
      });
    }
    showToast(
      lang === "ml"
        ? `✨ ഒറ്റ ക്ലിക്കിൽ എല്ലാ 7 ദിവസത്തെയും പരീക്ഷാ സീറ്റിംഗുകൾ (${totalGenerated} ദിവസങ്ങൾ) വിജയകരമായി ജനറേറ്റ് ചെയ്തു!`
        : `✨ Successfully batch generated seating for all ${totalGenerated} exam days at once!`,
      "success",
      lang === "ml" ? "ബാച്ച് ജനറേഷൻ വിജയം" : "Batch Seating Generated"
    );
  };

  // --- 7-DAY EXAM SCHEDULER (QUARTERLY, HALF-YEARLY, ANNUAL) ---
